import zlib from 'node:zlib';

/**
 * 將 PXG2 高壓縮原圖像素載荷解碼並輸出為標準 RGBA8888 PNG Buffer
 * 100% 採用上傳之原圖背景（map-home.png 1902x1380、map-street.png 1408x768）與徹底去背 26 件家具圖集（home-props-atlas.png 1024x470）
 */
export function decodePxg2ToRgba(b64, encodePNG) {
  const cleanB64 = b64.replace(/\s+/g, '');
  const raw = zlib.inflateSync(Buffer.from(cleanB64, 'base64'));
  if (raw.subarray(0, 4).toString('ascii') !== 'PXG2') {
    throw new Error('Invalid PXG2 header');
  }
  const tw = raw.readUInt16BE(4);
  const th = raw.readUInt16BE(6);
  const gw = raw.readUInt16BE(8);
  const gh = raw.readUInt16BE(10);
  const hasAlpha = raw[12] === 1;
  const nColors = raw[13];
  const nPatches = raw.readUInt16BE(14);
  let pos = 16;
  const pal = raw.subarray(pos, pos + nColors * 3);
  pos += nColors * 3;
  const grid = raw.subarray(pos, pos + gw * gh);
  pos += gw * gh;

  const fullIdx = new Uint8Array(tw * th);
  for (let y = 0; y < th; y++) {
    const gy = Math.floor((y * gh) / th) * gw;
    const rowOff = y * tw;
    for (let x = 0; x < tw; x++) {
      fullIdx[rowOff + x] = grid[gy + Math.floor((x * gw) / tw)];
    }
  }
  for (let p = 0; p < nPatches; p++) {
    const px = raw.readUInt16BE(pos);
    const py = raw.readUInt16BE(pos + 2);
    const pw = raw.readUInt16BE(pos + 4);
    const ph = raw.readUInt16BE(pos + 6);
    pos += 8;
    for (let y = 0; y < ph; y++) {
      const srcOff = pos + y * pw;
      const dstOff = (py + y) * tw + px;
      fullIdx.set(raw.subarray(srcOff, srcOff + pw), dstOff);
    }
    pos += pw * ph;
  }

  const rgba = new Uint8Array(tw * th * 4);
  for (let i = 0; i < fullIdx.length; i++) {
    const ci = fullIdx[i];
    const o = i * 4;
    if (hasAlpha && ci === 0) {
      rgba[o] = 0;
      rgba[o + 1] = 0;
      rgba[o + 2] = 0;
      rgba[o + 3] = 0;
    } else {
      const po = ci * 3;
      rgba[o] = pal[po];
      rgba[o + 1] = pal[po + 1];
      rgba[o + 2] = pal[po + 2];
      rgba[o + 3] = 255;
    }
  }
  return encodePNG(tw, th, rgba);
}

export const MAP_HOME_PXG2_B64 =
  '';

export const MAP_STREET_PXG2_B64 =
  '';

export const HOME_PROPS_ATLAS_PXG2_B64 =
  '';
